            #1;

            @(negedge clk);
            rst = 0;
            @(posedge clk);
            #2;
            #1;

            check_outputs(1'b0);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("\nTest %0d: Reset Priority (rst=0, d=1)", test_num);
            reset_dut();
            @(negedge clk);
            rst = 0;
            d = 1;
            @(posedge clk);
            #2;

            #1;


            check_outputs(1'b0);
